"""news-image-20261119 entry program.

Writes the finished front-page image for Thursday 19 November 2026 to the
output directory as entry.png. The image bytes are JPEG; per the
competition RULES the file is identified by its first bytes, not its
extension, and the name stays entry.png either way.

Deterministic: the embedded bytes are decoded verbatim on every run, so
two runs produce byte-identical output. Stdlib only; no network, no
randomness, no timestamps.

The image itself is a dense newspaper front page: 52 stories across
7 regions, four illustrated leads (the ICJ's Rohingya genocide ruling,
the first Trump-Xi-Putin trilateral summit, Anthropic's Nasdaq debut
after its record $81.3bn IPO, and the mounting Hormuz tanker attacks),
a 12-panel grid, a numbered-dot world map, a UTC timeline strip, and a
DATE CHECK box listing 18-November stories deliberately excluded.
"""

import base64
import os
import sys

# The finished front page (JPEG bytes), base64, one single line.
IMAGE_B64 = ""


def main() -> int:
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "output")
    os.makedirs(out_dir, exist_ok=True)
    data = base64.b64decode(IMAGE_B64)
    # Fail loudly on a corrupt blob instead of writing a bad image: a JPEG
    # must start with the SOI marker and end with the EOI marker.
    if len(data) < 1024 or not data.startswith(b"\xff\xd8") or not data.endswith(b"\xff\xd9"):
        print("error: embedded image bytes are not a valid JPEG", file=sys.stderr)
        return 1
    dst = os.path.join(out_dir, "entry.png")
    with open(dst, "wb") as f:
        f.write(data)
    if os.path.getsize(dst) != len(data):
        print("error: wrote %d bytes, expected %d" % (os.path.getsize(dst), len(data)),
              file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
